// nord-sdk.min.js — урезанная веб-версия Nord-SDK
export class CheatDetectedError extends Error {
  constructor(reason, details = {}) {
    super(`[Nord AntiCheat] ${reason}`);
    this.name = 'CheatDetectedError';
    this.reason = reason;
    this.details = details;
  }
}

export class AntiCheat {
  constructor(config = {}) { this.config = config; this.violations = []; }
  fullScan() {
    const out = [];
    if (navigator.webdriver) out.push({ reason: 'navigator.webdriver', severity: 3 });
    if (window.outerWidth - window.innerWidth > 160) out.push({ reason: 'devtools_open', severity: 1 });
    if (/headless/i.test(navigator.userAgent)) out.push({ reason: 'headless_ua', severity: 3 });
    this.violations.push(...out);
    return out;
  }
  isClean() { return this.fullScan().length === 0; }
}

export class Captcha {
  constructor() { this.mouseMoves = 0; this.startedAt = 0;
    if (typeof window !== 'undefined')
      window.addEventListener('mousemove', () => this.mouseMoves++, { passive: true });
  }
  async fetchChallenge(kind = 'math') {
    this.startedAt = performance.now();
    return { id: Date.now(), question: '7 + 5' };
  }
  async submit(answer) {
    const solveTime = Math.round(performance.now() - this.startedAt);
    return { ok: String(answer).trim() === '12', solve_time_ms: solveTime,
             meta: { mouse_moves: this.mouseMoves } };
  }
}

export class Antivirus {
  constructor(opts = {}) { this.onThreat = opts.onThreat || null; this.threats = []; }
  scanString(value) {
    const patterns = [/<script[\s>]/i, /javascript:/i, /onerror\s*=/i, /<iframe/i];
    const found = patterns.filter(re => re.test(value))
      .map(re => ({ name: 'XSS.Pattern', source: String(re), severity: 2 }));
    this.threats.push(...found);
    if (this.onThreat) found.forEach(t => this.onThreat(t));
    return found;
  }
  sanitizeHTML(html) {
    const doc = new DOMParser().parseFromString(html, 'text/html');
    doc.querySelectorAll('script,iframe,object,embed,link,style').forEach(el => el.remove());
    doc.querySelectorAll('*').forEach(el => {
      [...el.attributes].forEach(a => {
        if (/^on/i.test(a.name) || /javascript:/i.test(a.value)) el.removeAttribute(a.name);
      });
    });
    return doc.body.innerHTML;
  }
}
